package com.portfolio.dto;
import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.*;
public class TransactionDto {
 @Pattern(regexp="PORT\\d{4}") private String portfolioId; @Pattern(regexp="\\d{10}") private String accountNo; @Pattern(regexp="STK|BND|MMF|ETF") private String investmentType; private String investmentId; private String transactionType; @DecimalMin("0") private BigDecimal quantity; @DecimalMin("0") @Digits(integer=14,fraction=4) private BigDecimal price; @DecimalMin("0") @DecimalMax("9999999999999.99") private BigDecimal amount; private String currencyCode; private LocalDate transactionDate; private LocalTime transactionTime; private String processUser;
 public String getPortfolioId(){return portfolioId;} public void setPortfolioId(String v){portfolioId=v;} public String getAccountNo(){return accountNo;} public void setAccountNo(String v){accountNo=v;} public String getInvestmentType(){return investmentType;} public void setInvestmentType(String v){investmentType=v;} public String getInvestmentId(){return investmentId;} public void setInvestmentId(String v){investmentId=v;} public String getTransactionType(){return transactionType;} public void setTransactionType(String v){transactionType=v;} public BigDecimal getQuantity(){return quantity;} public void setQuantity(BigDecimal v){quantity=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public String getCurrencyCode(){return currencyCode;} public void setCurrencyCode(String v){currencyCode=v;} public LocalDate getTransactionDate(){return transactionDate;} public void setTransactionDate(LocalDate v){transactionDate=v;} public LocalTime getTransactionTime(){return transactionTime;} public void setTransactionTime(LocalTime v){transactionTime=v;} public String getProcessUser(){return processUser;} public void setProcessUser(String v){processUser=v;}
}
